import {drinkLiquidColor} from './food-colors.js';
import * as T from 'three';import {createResident,poseResident,disposeResident} from '../residents/residents.js';import {TEA_SEAT as S,TEA_RADIUS} from './tea-layout.js';
const PROFILES=Object.freeze({chinchilla:{label:'친칠라',mouthY:.76,reach:[-.5,-.1,-.4],sip:[-.6,0,-.5]},armadillo:{label:'아르마딜로',mouthY:.76,reach:[-.1,-.3,-.6],sip:[-.6,-.2,-.8]},capybara:{label:'카피바라',mouthY:.78,reach:[-.4,0,-.7],sip:[-.7,.1,-1]}});
const lerp=(a,b,t)=>a+(b-a)*t,smooth=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t);};
export function prepareTeaResident(model,root){const profile=PROFILES[model.userData.species];if(!profile)throw Error('Unapproved tea resident');model.updateMatrixWorld(true);const ray=new T.Raycaster(new T.Vector3(0,profile.mouthY,3),new T.Vector3(0,0,-1)),hit=ray.intersectObject(model.userData.parts.Head,true)[0];if(!hit)throw Error('Resident mouth contact unavailable');const mouth=hit.point.clone(),cup=new T.Group();cup.name='tea-time.shared-serving';root.add(cup);cup.visible=false;const mat=new T.MeshStandardMaterial({color:'#f2e5ca',roughness:.82}),coffee=new T.MeshStandardMaterial({color:'#704a32',roughness:.8});
 const add=(geo,material,x,y,z)=>{const mesh=new T.Mesh(geo,material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;cup.add(mesh);return mesh;};add(new T.CylinderGeometry(.105,.085,.18,32,1,true),mat,0,.09,0);add(new T.CylinderGeometry(.085,.085,.012,32),mat,0,.006,0);add(new T.CylinderGeometry(.096,.096,.005,32),coffee,0,.155,0);const rim=add(new T.TorusGeometry(.105,.005,8,32),mat,0,.18,0);rim.rotation.x=Math.PI/2;const handle=add(new T.TorusGeometry(.085,.015,10,24),mat,.11,.10,-.13);handle.rotation.y=Math.PI/2;handle.name='tea-time.cup-handle';
 return{model,cup,profile,mouth,root,disposed:false};}
export function poseTeaResident(a,p){if(a.disposed)return;const {model,cup,profile}=a,sip=Math.max(0,Math.min(1,p.sip??0)),reach=Math.max(0,Math.min(1,p.reach??0)),travel=smooth(sip),offset=p.sharing ? .32*smooth(reach)*(1-travel):0;model.position.set(p.x,p.y,p.z);model.rotation.set(0,p.yaw,0);model.position.x+=Math.sin(p.yaw)*offset;model.position.z+=Math.cos(p.yaw)*offset;if(!model.parent)a.root.add(model);model.visible=p.visible!==false;
 poseResident(model,{time:p.time??0,walking:!!p.walking&&!p.rigid&&!p.reducedMotion,headYaw:0,showBook:false});for(const role of['Arm.L','Arm.R']){const part=model.userData.parts[role],rest=model.userData.restPose[role];part.rotation.copy(rest.rotation);part.position.copy(rest.position);if(p.seated&&!p.sharing)part.rotation.x-=.12;if(p.sharing&&role==='Arm.R'){const q=profile.reach.map((v,i)=>lerp(v,profile.sip[i],travel)*smooth(reach));part.rotation.x+=q[0];part.rotation.y+=q[1];part.rotation.z+=q[2];}}
 // Correct only each original foot node's vertical offset. Geometry and normals stay pristine.
 if(p.walking&&!p.rigid){model.updateMatrixWorld(true);const vertex=new T.Vector3();for(const role of['Foot.L','Foot.R']){const foot=model.userData.parts[role];let min=Infinity;foot.traverse(n=>{if(!n.isMesh)return;for(let i=0;i<n.geometry.attributes.position.count;i++){vertex.fromBufferAttribute(n.geometry.attributes.position,i).applyMatrix4(n.matrixWorld);min=Math.min(min,vertex.y);}});const sign=role==='Foot.L'?1:-1,planted=Math.sin((p.time??0)*5)*sign<=0;if(planted||min<p.y)foot.position.y+=p.y-min;}model.updateMatrixWorld(true);}
 cup.visible=!!p.sharing;if(cup.visible){const mouth=new T.Vector3(0,a.mouth.y-.18,a.mouth.z+.11).applyAxisAngle(new T.Vector3(0,1,0),p.yaw).add(new T.Vector3(p.x,p.y,p.z));cup.position.set(lerp(S.cup.x,mouth.x,travel),lerp(S.cup.y,mouth.y,travel),lerp(S.cup.z,mouth.z,travel));cup.rotation.set(0,p.yaw,0);const coffee=cup.children[2];coffee.material.color.set(drinkLiquidColor(p.itemId));}model.updateMatrixWorld(true);cup.updateMatrixWorld(true);
}
export function disposeTeaResident(a){if(a.disposed)return;a.disposed=true;disposeResident(a.model);const materials=new Set();a.cup.traverse(n=>{n.geometry?.dispose();if(n.material)materials.add(n.material);});materials.forEach(m=>m.dispose());a.cup.removeFromParent();}
export function createTeaResidentAdapters(root,{isVisible=()=>true}={}){const visibility=(a,p)=>{a.model.visible=p?.visible!==false&&isVisible(p);a.cup.visible=!!a.sharing&&a.model.visible;};return Object.fromEntries(Object.entries(PROFILES).map(([id,p])=>[id,{label:p.label,radius:TEA_RADIUS,canSip:true,async load(){const model=await createResident(id,{showBook:false});try{return prepareTeaResident(model,root);}catch(e){disposeResident(model);throw e;}},pose(a,p){poseTeaResident(a,p);a.sharing=!!p.sharing;visibility(a,p);},visibility,dispose:disposeTeaResident}]));}
